from lib import *
S = SS('g34')
steps = [
    step("不同程序的二进制大小(darwin/arm64,CGO_ENABLED=0):println 版 1831778 字节(1.75 MiB),fmt.Println 版 2429714 字节(2.32 MiB),加 encoding/json 3766466 字节(3.59 MiB),加 net/http 客户端 8316338 字节(7.93 MiB),加 net/http 服务端 8217154 字节(7.84 MiB)。每个程序用 -ldflags=\"-s -w\" 之后都小 33%–35%:1.14、1.51、2.36、5.35、5.29 MiB。", t=tl(S(1)), done=lidx(S(1), 'println 版', 'fmt.Println 版'), mark=lidx(S(1), '加 encoding/json', '加 net/http 客户端', '加 net/http 服务端'), b=bars([['println 版(MiB)', 1.75, '1.75'], ['fmt.Println 版', 2.32, '2.32'], ['+ encoding/json', 3.59, '3.59'], ['+ net/http 客户端', 7.93, '7.93'], ['net/http 版 -s -w', 5.35, '5.35']], 7.93, done=[0, 1], mark=[2, 3, 4]), kv=KV([['不导入 fmt 的 hello', '1.75 MiB'], ['fmt.Println', '2.32 MiB(+0.57)'], ['+ encoding/json', '3.59 MiB'], ['+ net/http', '7.8–7.9 MiB'], ['-s -w 的效果', '统一小 33%–35%']], ['+ net/http'])),
    step("-s 与 -w 各去掉了什么(fmt.Println 版):默认 2429714 字节;-ldflags=-s 1587714 字节(与 -s -w 相同:去掉符号表时 DWARF 也一起没了);-ldflags=-w 1686674 字节(只去 DWARF);-trimpath 2396642 字节,-trimpath 加 -s -w 1571202 字节。size -m 看默认构建的段:__TEXT 1343488 字节(__text 632260、__gopclntab 650154、__rodata 40578),__DATA_CONST 144880(__go_type 136160),__DATA 213424。pclntab 与代码一样大。", t=tl(S(2)), done=lidx(S(2), '默认:', '-ldflags=-s(', '-ldflags=-w('), mark=lidx(S(2), '-trimpath', '__gopclntab', '__text'), b=bars([['默认(KiB)', 2373, '2373'], ['-s(KiB)', 1550, '1550'], ['-w(KiB)', 1647, '1647'], ['__text(KiB)', 617, '617'], ['__gopclntab(KiB)', 635, '635']], 2373, done=[1, 2], mark=[3, 4]), kv=KV([['默认', '2429714 字节'], ['-s', '1587714 字节(与 -s -w 相同)'], ['-w', '1686674 字节'], ['__text / __gopclntab', '632260 / 650154 字节——一样大']], ['__text / __gopclntab'])),
    step("体积用在哪(net/http 服务端版,默认构建):nm 里占文件空间的符号合计 5483407 字节(文件 8217154 字节)。按包:runtime 2319311 字节(42.3%)、_type:*(类型描述符)535536(9.8%)、go:*(编译器生成的数据)483400(8.8%)、vendor/golang 224122、crypto/tls 222035、crypto/internal/fips140/nistec 137648、net 136336、net/http/internal/http2 123867、net/http 107073。最大的符号是 runtime.pclntab 1681680 字节。另外 BSS 里有 crypto/internal/fips140/drbg.memory 33554432 字节(32 MiB)——不占文件空间,但运行时要映射内存。", t=tl(S(3)), done=lidx(S(3), 'nm 里占文件空间', 'runtime '), mark=lidx(S(3), 'runtime.pclntab', 'drbg.memory', '_type:*'), b=bars([['runtime(KiB)', 2265, '2265'], ['_type:*', 523, '523'], ['go:* 生成数据', 472, '472'], ['crypto/tls', 217, '217'], ['net/http', 105, '105']], 2265, done=[0], mark=[1, 2, 3, 4]), kv=KV([['runtime', '2319311 字节,占 42.3%'], ['最大的符号', 'runtime.pclntab 1681680 字节'], ['BSS', 'fips140/drbg.memory 32 MiB:不占文件,占内存映射'], ['net/http 自己', '107073 字节(依赖的 crypto、net 等更大)']], ['BSS'])),
    step("-s -w 之后还能看到函数名吗:默认构建 1831906 字节,go tool nm 有 1826 个符号;-ldflags=\"-s -w\" 构建 1195362 字节,go tool nm 只剩 42 个符号;两种构建下 panic 的栈回溯里都有 main.boom(...) 与 main.main()——回溯靠的是 pclntab,不靠符号表。", t=tl(S(4)), mark=lidx(S(4), '默认', '-ldflags'), b=bars([['默认的符号数', 1826, '1826'], ['-s -w 的符号数', 42, '42']], 1826, done=[1], mark=[0]), kv=KV([['符号表', '1826 → 42 个符号'], ['panic 栈回溯', '函数名仍在(pclntab)'], ['含义', '剥离不影响运行与诊断,影响 nm 与调试器']], ['panic 栈回溯'])),
    step("反射会让链接器保留更多方法:同一个类型有 200 个导出方法。不用反射、只直接调 M1:2429698 字节,符号表里没有 M<数字>;用 reflect.TypeOf(…).Name()(用了反射但不调方法):2446258 字节,仍是 0 个;用 reflect.Value.MethodByName(动态名字):3444562 字节,200 个方法全部保留。方法数 N 变化:N = 0 是 3349922 字节(用 MethodByName 本身就比 hello 多约 0.9 MiB),N = 20 多 17680 字节、N = 100 多 55456 字节、N = 200 多 94640 字节(每个方法约 470 字节)。", t=tl(S(5)), done=lidx(S(5), '不用反射', 'reflect.TypeOf'), mark=lidx(S(5), 'MethodByName', 'N = 200'), b=bars([['直接调用(KiB)', 2373, '2373'], ['TypeOf.Name', 2389, '2389'], ['MethodByName N=0', 3272, '3272'], ['MethodByName N=200', 3364, '3364']], 3364, done=[0, 1], mark=[2, 3]), kv=KV([['不用反射', '2429698 字节;200 个方法都被丢弃'], ['reflect.TypeOf(...).Name()', '+16 KB;方法仍被丢弃'], ['MethodByName', '+约 0.9 MiB 固定成本,方法全部保留'], ['每个方法', '约 470 字节']], ['MethodByName'])),
    step("不同平台的 hello world(fmt.Println 版,交叉编译):darwin/arm64 2429714 字节(2.32 MiB),-s -w 1587714;linux/amd64 2346705(2.24 MiB),-s -w 1515680;linux/arm64 2342341(2.23 MiB),-s -w 1573024;windows/amd64 2496512(2.38 MiB),-s -w 1660416(1.58 MiB)。", t=tl(S(6)), done=lidx(S(6), 'darwin/arm64', 'linux/amd64', 'linux/arm64'), mark=lidx(S(6), 'windows/amd64'), kv=KV([['darwin/arm64', '2.32 MiB → 1.51 MiB'], ['linux/amd64', '2.24 MiB → 1.45 MiB'], ['linux/arm64', '2.23 MiB → 1.50 MiB'], ['windows/amd64', '2.38 MiB → 1.58 MiB']], ['windows/amd64'])),
]
A = mkartg('g34', 34, 'Go,二进制体积,ldflags,pclntab,链接器,真实验证,动画演示',
    '在 Go 1.27.1 里实测二进制体积:hello world 1.75–2.32 MiB,加 encoding/json 3.59 MiB,加 net/http 约 7.9 MiB;-ldflags="-s -w" 统一小 33%–35%;pclntab 与代码一样大;panic 的栈回溯靠 pclntab,所以剥离符号表后仍有函数名;按包统计 runtime 占 42%;通过 reflect.Value.MethodByName 调用方法会一次多约 0.9 MiB 并保留所有导出方法(每个约 470 字节);各平台 hello world 的大小。',
    'Go 的二进制大,主要因为它自带运行时、垃圾回收、类型信息与完整的函数表。这篇用真实构建量出:不同依赖带来多少、-s -w 去掉了什么、pclntab 是什么、体积都花在哪些包上,以及反射用法怎样让链接器没法丢掉不用的方法。',
    [('~0.9 MiB', '只要用了 reflect.Value.MethodByName,二进制就多这么多(再加每个方法约 470 字节)'), ('33%–35%', '-ldflags="-s -w" 对各种程序的体积缩减'), ('pclntab', '与 __text 一样大(650154 与 632260 字节);panic 回溯靠它,剥离符号后函数名仍在')],
    [('依赖决定体积', '<p>最小的 hello world 约 1.75 MiB(只用内建 <code>println</code>,不导入 <code>fmt</code>),<code>fmt</code> 带来 0.57 MiB,<code>encoding/json</code> 再加 1.27 MiB,<code>net/http</code> 把它推到 7.8–7.9 MiB——因为它拖进 TLS、x509、HTTP/2、net 等一大串包。体积主要是“导入了什么”,而不是你自己写了多少代码。</p>'),
     ('-s 与 -w', '<p><code>-s</code> 去掉符号表,<code>-w</code> 去掉 DWARF 调试信息;实测只写 <code>-s</code> 就和 <code>-s -w</code> 一样大(DWARF 随符号表一起没了),只写 <code>-w</code> 单独能省约 0.71 MiB(2429714 → 1686674 字节)。<code>-trimpath</code> 只是把路径换成相对形式,体积只小一点(省约 33 KB)。代价是 <code>go tool nm</code> 与调试器能看到的东西变少,<b>不影响运行,也不影响 panic 的栈回溯</b>。</p>'),
     ('体积用在哪', '<p>按符号统计,运行时(含它的类型与函数表)占了 4 成以上,最大的单个符号是 <code>runtime.pclntab</code>(程序计数器到函数、文件、行号的映射表,栈回溯、垃圾回收的栈扫描都要用它);<code>_type:*</code> 是类型描述符(反射与接口用)。BSS 里有一个 32 MiB 的 <code>crypto/internal/fips140/drbg.memory</code>:不占文件空间,但会占运行时的内存映射(我没有量它的实际驻留内存)。</p>'),
     ('剥离后还有函数名', '<p>剥离符号表后 <code>go tool nm</code> 从 1826 个符号变成 42 个,但 panic 的回溯照样显示 <code>main.boom</code>,因为回溯读的是 pclntab。所以生产构建加 <code>-s -w</code> 通常是安全的;想保留符号以便事后分析就别加。</p>'),
     ('反射与死代码消除', '<p>链接器会丢掉没被引用的函数,但如果程序里出现 <code>MethodByName</code> 这样“按名字找方法”的反射调用,编译器无法知道会调哪个,所以把能被反射到的导出方法全部保留(实验里 200 个方法全留着,符号表里 200 个)。仅仅用 <code>reflect.TypeOf</code> 不会触发。这一点只看到现象,我没有读链接器里决定保留的那段代码。</p>'),
     ('不同平台', '<p>交叉编译出的 hello world 大小相近,windows 稍大。数字都是 <code>CGO_ENABLED=0</code>、<code>go build</code> 默认选项的结果,没有试 <code>-gcflags</code>、UPX 等其它减小体积的手段。</p>')],
    steps,
    [ENV_G + '。所有大小来自真实构建(go build 默认选项,CGO_ENABLED=0);段大小用 macOS 的 size -m;符号大小用 go tool nm -size(BSS 符号单独统计);panic 回溯来自真实运行',
     '没有验证:UPX 压缩、-gcflags 与 -ldflags 的其它体积选项、链接器死代码消除的具体算法、BSS 的 32 MiB 在运行时的实际驻留内存、Linux 上 ELF 各段的占用(只在 macOS 上看了段)、go build -buildmode=pie 等其它构建模式'],
    '二进制体积')
